#[no_mangle]
pub unsafe extern "C" fn akar_scroll_area_begin(
    ctx: *mut AkarCtx,
    rect: *const f32,
    scroll_y: *mut f32,
    content_height: f32,
) -> f32 {
    let ctx = unsafe { &mut *ctx };
    let rect = unsafe { *(rect as *const [f32; 4]) };
    let resp = akar_components::scroll_area_begin(
        &mut ctx.core,
        rect,
        unsafe { &mut *scroll_y },
        content_height,
    );
    resp.content_y
