pub unsafe extern "C" fn akar_new_fixed_leaf(ctx: *mut AkarCtx, w: f32, h: f32) -> u64 {
    use akar_layout::{length, Dimension, Size, Style};
    let ctx = unsafe { &mut *ctx };
    let style = Style {
        size: Size {
            width: if w > 0.0 {
                length(w)
            } else {
                Dimension::auto()
            },
            height: if h > 0.0 {
                length(h)
            } else {
                Dimension::auto()
            },
        },
        flex_shrink: 0.0,
        ..Default::default()
    };
    ctx.layout.new_leaf(style).into()
}

